<template>
  <view v-if="!desktop">
    <PipeCreationPanel :creation="creation" />
    <LegacyLeakNetworkPanel v-bind="props" :creation-active="creation.draft.active"
      @expand="$emit('expand')" @collapse="$emit('collapse')" @toggle-visible="$emit('toggle-visible')"
      @toggle-facility="$emit('toggle-facility', $event)" @refresh="$emit('refresh')"
      @fit="$emit('fit', 'all')" @start-creation="creation.start" />
  </view>
  <view v-else class="network-layer" :class="{ 'network-layer--google': provider === 'google' }">
    <view v-if="collapsed" class="network-layer__collapsed">
      <button class="network-layer__collapsed-button" type="button" :aria-label="t('pipePanel')" @click.stop="$emit('expand')">
        <image class="network-layer__collapsed-icon" src="/static/icons/layers.svg" mode="aspectFit" /><text>{{ t("pipePanel") }}</text>
      </button>
    </view>
    <view v-else class="network-panel" @click.stop>
      <view class="network-panel__viewport" :class="{ 'network-panel__viewport--edit': page === 'edit' }">
        <view class="network-panel__page network-panel__page--home" :inert="page === 'edit' ? true : undefined" :aria-hidden="page === 'edit'">
          <view class="network-panel__head">
            <view class="network-panel__heading"><text class="network-panel__title">{{ t("pipeLayer") }}</text><text class="network-panel__subtitle">{{ providerLabel }}</text></view>
            <button class="network-panel__icon-button" type="button" :aria-label="t('collapsePanel')" :title="t('collapsePanel')" @click="$emit('collapse')"><image class="network-panel__action-icon" src="/static/icons/chevron-up.svg" mode="aspectFit" /></button>
          </view>
          <view class="network-panel__summary"><view><text class="network-panel__summary-value">{{ pipes.length }}</text><text class="network-panel__summary-label">{{ t("pipeLayer") }}</text></view><view><text class="network-panel__summary-value">{{ facilities.length }}</text><text class="network-panel__summary-label">{{ t("facilityDisplay") }}</text></view><view class="network-panel__summary-status" :class="{ 'network-panel__summary-status--loading': loading }"><text class="network-panel__status-dot"></text><text>{{ loading ? t("networkLayerLoading") : loaded ? t("pipeApiLayer") : t("networkLayerLoadFailed") }}</text></view></view>
          <view class="network-panel__body">
            <view v-if="creation.hasUnsavedChanges.value" class="network-panel__draft-banner"><view><text class="network-panel__draft-title">{{ t("draftInProgress") }}</text><text class="network-panel__draft-copy">{{ t("draftSavedAcrossViews") }}</text></view><button type="button" @click="page = 'edit'">{{ t("continueEditing") }}</button></view>
            <view class="network-panel__section"><view class="network-panel__section-head"><text>{{ t("pipeDisplay") }}</text><button class="network-panel__text-button" type="button" :aria-label="t('refreshNetwork')" :title="t('refreshNetwork')" @click="$emit('refresh')"><image class="network-panel__action-icon" src="/static/icons/refresh-cw.svg" mode="aspectFit" /></button></view><button class="network-panel__toggle-row" :class="{ 'network-panel__toggle-row--active': visible }" type="button" @click="$emit('toggle-visible')"><text class="network-panel__swatch network-panel__swatch--pipe"></text><text class="network-panel__toggle-label">{{ t("pipeLayer") }}</text><text class="network-panel__toggle-count">{{ pipes.length }}</text><text class="network-panel__switch" :class="{ 'network-panel__switch--on': visible }"></text></button></view>
            <view class="network-panel__section"><view class="network-panel__section-head"><text>{{ t("facilityDisplay") }}</text><text class="network-panel__section-count">{{ facilities.length }}</text></view><button v-for="item in facilityItems" :key="item.type" class="network-panel__toggle-row" :class="{ 'network-panel__toggle-row--active': facilityVisibility[item.type] }" type="button" @click="$emit('toggle-facility', item.type)"><text class="network-panel__swatch" :style="{ backgroundColor: item.color }"></text><text class="network-panel__toggle-label">{{ item.label }}</text><text class="network-panel__toggle-count">{{ item.count }}</text><text class="network-panel__switch" :class="{ 'network-panel__switch--on': facilityVisibility[item.type] }"></text></button></view>
            <view class="network-panel__section network-panel__section--devices"><view class="network-panel__section-head"><text>{{ t("deviceBinding") }}</text><text class="network-panel__section-count">{{ devicePoints.length }}</text></view><view v-for="item in deviceItems" :key="item.key" class="network-panel__device-row"><text class="network-panel__swatch" :style="{ backgroundColor: item.color }"></text><text class="network-panel__toggle-label">{{ item.label }}</text><text class="network-panel__toggle-count">{{ item.count }}</text></view></view>
            <view v-if="errorMessage" class="network-panel__error"><text>{{ errorMessage }}</text><button v-if="source !== 'w84'" class="network-panel__retry" type="button" @click="$emit('refresh')">{{ t("retryNetworkLayer") }}</button></view>
            <view class="network-panel__legend"><text class="network-panel__legend-title">{{ t("pipeLegend") }}</text><view class="network-panel__legend-row"><text class="network-panel__legend-line network-panel__legend-line--active"></text><text>{{ t("activePipe") }}</text></view><view class="network-panel__legend-row"><text class="network-panel__legend-line network-panel__legend-line--inactive"></text><text>{{ t("inactivePipe") }}</text></view><view class="network-panel__legend-row"><text class="network-panel__legend-line network-panel__legend-line--unassessed"></text><text>{{ t("unassessed") }}</text></view></view>
          </view>
          <view class="network-panel__footer"><view class="network-panel__footer-copy"><text>{{ t("pipeCount", { pipes: pipes.length, facilities: facilities.length }) }}</text><text v-if="creation.hasUnsavedChanges.value" class="network-panel__footer-draft">{{ t("draftInProgress") }}</text></view><view class="network-panel__footer-actions"><select v-if="regionOptions.length > 2" class="network-panel__region-select" :value="selectedRegion" :aria-label="t('networkRegion')" @change="selectRegion"><option v-for="item in regionOptions" :key="item.key" :value="item.key">{{ item.label }}</option></select><button class="network-panel__locate" type="button" :aria-label="t('locateNetwork')" :title="t('locateNetwork')" @click="$emit('fit', selectedRegion)"><image class="network-panel__action-icon" src="/static/icons/crosshair.svg" mode="aspectFit" /></button><button class="network-panel__add-button" type="button" @click="beginCreation">＋ {{ t("add") }}</button></view></view>
        </view>
        <view class="network-panel__page network-panel__page--edit" :inert="page === 'home' ? true : undefined" :aria-hidden="page === 'home'"><PipeCreationPanel v-if="creation.draft.active" :creation="creation" embedded @back="returnHome" /></view>
      </view>
    </view>
  </view>
</template>

<script setup lang="ts">
import { computed, ref, watch } from "vue";
import type { FacilityType, LeakMonitorFacility, LeakMonitorPipe, MapDevicePoint, MapRegion } from "../types";
import type { PipeCreationController } from "../pipeCreation";
import { useLeakMonitorI18n } from "../i18n";
import PipeCreationPanel from "./PipeCreationPanel.vue";
import LegacyLeakNetworkPanel from "./LegacyLeakNetworkPanel.vue";
import { useDesktopMapEditor } from "../composables/useDesktopMapEditor";
import { networkDepartmentKey } from "../networkViewport";

const props = withDefaults(defineProps<{ provider?: "tencent" | "google"; providerLabel: string; pipes?: LeakMonitorPipe[]; facilities?: LeakMonitorFacility[]; regions?: MapRegion[]; devicePoints?: MapDevicePoint[]; visible?: boolean; collapsed?: boolean; loaded?: boolean; loading?: boolean; errorMessage?: string; facilityVisibility?: Record<FacilityType, boolean>; source?: "api" | "w84"; creation: PipeCreationController }>(), { provider: "tencent", pipes: () => [], facilities: () => [], regions: () => [], devicePoints: () => [], visible: true, collapsed: true, loaded: false, loading: false, errorMessage: "", facilityVisibility: () => ({ VALVE: true, HYDRANT: true, PUMP: true }), source: "api" });
const emit = defineEmits<{ (event: "expand"): void; (event: "collapse"): void; (event: "toggle-visible"): void; (event: "toggle-facility", type: FacilityType): void; (event: "refresh"): void; (event: "fit", region?: string): void; }>();
const { t } = useLeakMonitorI18n();
const desktop = useDesktopMapEditor();
const page = ref<"home" | "edit">(props.creation.draft.active ? "edit" : "home");
const selectedRegion = ref("all");
function selectRegion(event: Event) { selectedRegion.value = (event.target as HTMLSelectElement).value; emit("fit", selectedRegion.value); }
function beginCreation() { if (!props.creation.draft.active) props.creation.start("pipe"); page.value = "edit"; }
function returnHome() { props.creation.draft.drawingActive = false; props.creation.selectPlacementType(""); page.value = "home"; }
watch(() => props.creation.draft.active, (active) => { page.value = active ? "edit" : "home"; });
const facilityItems = computed(() => { const count = props.facilities.reduce<Record<FacilityType, number>>((result, facility) => { result[facility.facilityType] += 1; return result; }, { VALVE: 0, HYDRANT: 0, PUMP: 0 }); return [{ type: "VALVE" as const, label: t("facilityValve"), count: count.VALVE, color: "#2F80ED" }, { type: "HYDRANT" as const, label: t("facilityHydrant"), count: count.HYDRANT, color: "#F59E0B" }, { type: "PUMP" as const, label: t("facilityPump"), count: count.PUMP, color: "#8B5CF6" }]; });
const deviceItems = computed(() => { const count = props.devicePoints.reduce<Record<string, number>>((result, point) => { const key = point.facilityType || "NONE"; result[key] = (result[key] || 0) + 1; return result; }, {}); return [{ key: "VALVE", label: t("boundValve"), count: count.VALVE || 0, color: "#2F80ED" }, { key: "HYDRANT", label: t("boundHydrant"), count: count.HYDRANT || 0, color: "#F59E0B" }, { key: "PUMP", label: t("boundPump"), count: count.PUMP || 0, color: "#8B5CF6" }, { key: "NONE", label: t("unboundDevice"), count: count.NONE || 0, color: "#64748B" }]; });
const regionOptions = computed(() => {
  const ids = new Set<string>();
  const visibleItems = [...(props.visible ? props.pipes : []), ...props.facilities.filter((facility) => props.facilityVisibility[facility.facilityType])];
  visibleItems.forEach((item) => ids.add(networkDepartmentKey(item.deptId)));
  const options = [{ key: "all", label: t("allNetwork") }];
  if (ids.has("none")) options.push({ key: "none", label: t("unassignedNetwork") });
  [...ids].filter((id) => id !== "none").sort((a, b) => Number(a) - Number(b)).forEach((id) => options.push({ key: id, label: props.regions.find((region) => String(region.id) === id)?.name || `${t("networkRegion")} ${id}` }));
  return options;
});
</script>

<style scoped lang="scss">
.network-layer { position: absolute; inset: 0; z-index: 20; pointer-events: none; }.network-layer__collapsed { position: absolute; top: 18px; left: 18px; pointer-events: auto; }.network-layer__collapsed-button { display: inline-flex; align-items: center; gap: 8px; height: 38px; padding: 0 13px; color: #1f2d3d; font-size: 13px; font-weight: 700; background: #fff; border: 1px solid rgba(201,216,232,.95); border-radius: 5px; box-shadow: 0 8px 20px rgba(18,43,70,.14); }.network-layer__collapsed-button::after, .network-panel button::after { border: 0; }.network-layer__collapsed-icon, .network-panel__action-icon { display: block; width: 16px; height: 16px; }
.network-panel { position: absolute; top: 18px; left: 18px; width: min(570px, calc(100vw - 120px)); max-height: min(900px, calc(100% - 36px)); overflow: hidden; pointer-events: auto; background: #fff; border: 1px solid rgba(201,216,232,.95); border-radius: 8px; box-shadow: 0 16px 34px rgba(18,43,70,.18); }.network-panel__viewport { display: flex; width: 200%; transition: transform .28s ease; }.network-panel__viewport--edit { transform: translateX(-50%); }.network-panel__page { display: flex; flex-direction: column; width: 50%; min-width: 50%; max-height: min(900px, calc(100vh - 36px)); }.network-panel__body { flex: 1; min-height: 0; overflow-y: auto; padding-bottom: 4px; }.network-panel__head, .network-panel__footer, .network-panel__section-head, .network-panel__toggle-row, .network-panel__legend-row { display: flex; align-items: center; }.network-panel__head, .network-panel__footer, .network-panel__section-head { justify-content: space-between; gap: 9px; }.network-panel__head { flex: none; min-height: 54px; padding: 0 14px 0 18px; background: linear-gradient(180deg,#fff 0%,#f5f8fb 100%); border-bottom: 1px solid #e6edf4; }.network-panel__heading { flex: 1; min-width: 0; }.network-panel__title, .network-panel__subtitle, .network-panel__draft-title, .network-panel__draft-copy, .network-panel__footer-draft { display: block; }.network-panel__title { color: #1f2d3d; font-size: 18px; font-weight: 800; }.network-panel__subtitle { margin-top: 3px; color: #64748b; font-size: 12px; font-weight: 700; }.network-panel__icon-button, .network-panel__text-button, .network-panel__locate { display: inline-flex; align-items: center; justify-content: center; flex: none; margin: 0; padding: 0; color: #52677d; background: #eef5fb; border: 0; border-radius: 5px; }.network-panel__icon-button { width: 32px; height: 32px; }.network-panel__text-button, .network-panel__locate { width: 30px; height: 30px; }
.network-panel__summary { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 12px; margin: 0 16px; padding: 12px 0; border-bottom: 1px solid #edf2f7; }.network-panel__summary-value, .network-panel__summary-label { display: block; }.network-panel__summary-value { color: #1d66c2; font-size: 22px; font-weight: 900; line-height: 24px; }.network-panel__summary-label { margin-top: 3px; color: #64748b; font-size: 12px; font-weight: 700; }.network-panel__summary-status { grid-column: 1 / -1; display: flex; align-items: center; gap: 6px; padding-top: 3px; color: #047857; font-size: 12px; }.network-panel__summary-status--loading { color: #b45309; }.network-panel__status-dot { width: 7px; height: 7px; flex: none; background: currentColor; border-radius: 50%; }.network-panel__draft-banner { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 12px 16px 0; padding: 11px 12px; background: #eef7ff; border: 1px solid #c6e0f4; border-radius: 7px; }.network-panel__draft-title { color: #1e5e91; font-size: 12px; font-weight: 800; }.network-panel__draft-copy { margin-top: 3px; color: #6a8499; font-size: 11px; }.network-panel__draft-banner button { height: 28px; margin: 0; padding: 0 10px; color: #fff; font-size: 11px; background: #1e73b5; border: 0; border-radius: 5px; }
.network-panel__section { margin: 12px 16px 0; }.network-panel__section-head { color: #26384d; font-size: 13px; font-weight: 800; }.network-panel__section-count, .network-panel__toggle-count { color: #64748b; font-size: 12px; }.network-panel__toggle-row { width: 100%; min-height: 36px; margin-top: 5px; padding: 0 9px; gap: 9px; color: #31435a; text-align: left; background: #fff; border: 1px solid transparent; border-radius: 5px; }.network-panel__toggle-row--active { color: #1e293b; background: #f6fbff; border-color: #e2ebf3; }.network-panel__swatch { width: 9px; height: 9px; flex: none; border-radius: 50%; }.network-panel__swatch--pipe { background: #16a34a; }.network-panel__toggle-label { flex: 1; min-width: 0; font-size: 13px; font-weight: 700; }.network-panel__switch { width: 24px; height: 14px; background: #cbd5e1; border-radius: 10px; }.network-panel__switch--on { background: #3182ce; }.network-panel__switch--on::after { content: ""; display: block; width: 10px; height: 10px; margin: 2px 2px 0 12px; background: #fff; border-radius: 50%; }.network-panel__switch:not(.network-panel__switch--on)::after { content: ""; display: block; width: 10px; height: 10px; margin: 2px; background: #fff; border-radius: 50%; }.network-panel__device-row { display: flex; align-items: center; gap: 9px; min-height: 30px; padding: 0 9px; }.network-panel__error { display: flex; align-items: center; gap: 8px; margin: 12px 16px 0; padding: 9px; color: #b42318; font-size: 12px; line-height: 1.35; background: #fff1ee; border: 1px solid #ffd3cb; border-radius: 5px; }.network-panel__error > text { flex: 1; }.network-panel__retry { flex: none; margin: 0; padding: 4px 8px; color: #b42318; font-size: 12px; background: #fff; border: 1px solid #f1aaa0; border-radius: 4px; }
.network-panel__legend { display: grid; gap: 7px; margin: 12px 16px 0; padding-top: 11px; border-top: 1px solid #edf2f7; }.network-panel__legend-title { color: #52677d; font-size: 12px; font-weight: 800; }.network-panel__legend-row { gap: 8px; color: #52677d; font-size: 12px; }.network-panel__legend-line { width: 28px; height: 4px; border-radius: 2px; }.network-panel__legend-line--active { background: #16a34a; }.network-panel__legend-line--inactive { background: repeating-linear-gradient(90deg,#94a3b8 0 5px,transparent 5px 8px); }.network-panel__legend-line--unassessed { background: #cbd5e1; }.network-panel__footer { flex: none; min-height: 56px; margin: 10px 16px 0; color: #64748b; font-size: 12px; border-top: 1px solid #edf2f7; }.network-panel__footer-copy { min-width: 0; }.network-panel__footer-draft { margin-top: 3px; color: #1e73b5; font-size: 11px; font-weight: 700; }.network-panel__footer-actions { display: flex; align-items: center; gap: 8px; }.network-panel__add-button { height: 34px; margin: 0; padding: 0 14px; color: #fff; font-size: 12px; font-weight: 800; background: #1e73b5; border: 0; border-radius: 5px; }.network-layer--google .network-layer__collapsed, .network-layer--google .network-panel { top: 72px; }
@media (max-width: 900px) { .network-layer__collapsed { top: 68px; left: 10px; }.network-panel { top: 68px; left: 10px; width: min(380px, calc(100vw - 20px)); max-height: calc(100% - 78px); }.network-panel__page { max-height: calc(100vh - 78px); }.network-layer--google .network-layer__collapsed, .network-layer--google .network-panel { top: 84px; } }
.network-panel__region-select { max-width: 130px; height: 30px; padding: 0 6px; color: #52677d; font-size: 11px; background: #f7fafc; border: 1px solid #cad9e6; border-radius: 5px; }
@media (min-width: 901px) {
  .network-panel { height: min(900px, calc(100% - 36px)); }
  .network-panel__viewport, .network-panel__page { height: 100%; max-height: none; min-height: 0; }
  .network-layer--google .network-panel { height: min(900px, calc(100% - 90px)); }
}
</style>
